from __future__ import annotations

import os
import re
import shutil
from dataclasses import dataclass
from pathlib import Path
from urllib.parse import urlsplit

import yaml

from kbforge.config import (
    VALID_CHUNKING_STRATEGIES,
    VALID_RANKING_MODES,
    ChunkingConfig,
    CrawlConfig,
    IndexConfig,
)
from kbforge.urls import normalize_url

GENERATED_CONFIG_DIRNAME = ".kbforge-configs"
GENERATED_CONFIG_MARKER = (
    "# Generated by the kbforge URL build workflow. "
    "Re-run the command instead of editing this file."
)

STRATEGY_LABELS = {
    "fixed": "fixed-size",
    "sentence": "sentence-based",
    "paragraph": "paragraph-based",
}
STRATEGY_MENU = (
    ("fixed", "Fixed-size"),
    ("sentence", "Sentence-based"),
    ("paragraph", "Paragraph-based"),
)


class UrlBuildError(ValueError):
    """Raised when URL workflow input or a destination is invalid."""


@dataclass(frozen=True)
class UrlBuildOptions:
    url: str
    hostname: str
    max_pages: int
    max_depth: int
    include_subdomains: bool
    chunking_strategy: str
    chunk_size: int
    chunk_overlap: int
    ranking_modes: tuple[str, ...]
    output: str | None = None


@dataclass(frozen=True)
class UrlBuildPaths:
    output_dir: Path
    config_path: Path
    archive_path: Path


def validate_website_url(value: str) -> tuple[str, str]:
    """Return ``(normalized_url, hostname)`` for a crawlable website URL."""
    if not isinstance(value, str) or not value.strip():
        raise UrlBuildError("website URL must not be empty")
    raw = value.strip()
    try:
        parts = urlsplit(raw)
        _ = parts.port
        hostname = parts.hostname
    except ValueError as exc:
        raise UrlBuildError(f"invalid website URL {raw!r}: {exc}") from exc
    if parts.scheme.lower() not in ("http", "https") or not hostname:
        raise UrlBuildError("website URL must start with http:// or https://")
    if parts.username is not None or parts.password is not None:
        raise UrlBuildError("website URL must not contain credentials")
    if any(character.isspace() for character in hostname):
        raise UrlBuildError("website URL contains an invalid hostname")
    normalized = normalize_url(raw)
    if normalized is None:
        raise UrlBuildError(f"invalid website URL: {raw!r}")
    return normalized, hostname.lower()


def output_slug(hostname: str) -> str:
    """Build a readable, filesystem-safe output name from a hostname."""
    host = hostname.lower()
    if host.startswith("www."):
        host = host[4:]
    try:
        host = host.encode("idna").decode("ascii")
    except UnicodeError:
        pass
    slug = re.sub(r"[^a-z0-9]+", "-", host).strip("-")
    slug = slug[:80].rstrip("-")
    return slug or "website"


def default_output_path(hostname: str, cwd: str | Path | None = None) -> Path:
    root = Path(cwd or Path.cwd()) / "output"
    return root / output_slug(hostname)


def resolve_build_paths(
    output: str | Path | None,
    hostname: str,
    cwd: str | Path | None = None,
) -> UrlBuildPaths:
    """Resolve and validate package, generated-config and ZIP paths."""
    cwd_path = Path(cwd or Path.cwd())
    output_root = (cwd_path / "output").resolve()
    if output is None:
        candidate = default_output_path(hostname, cwd_path)
    else:
        raw = Path(output).expanduser()
        candidate = raw if raw.is_absolute() else cwd_path / raw
    output_dir = candidate.resolve()

    if output_dir == output_root or not output_dir.is_relative_to(output_root):
        raise UrlBuildError("output directory must be inside output/")
    config_dir = output_root / GENERATED_CONFIG_DIRNAME
    if output_dir == config_dir or output_dir.is_relative_to(config_dir):
        raise UrlBuildError(
            f"output directory must not be inside {GENERATED_CONFIG_DIRNAME}/"
        )

    relative = output_dir.relative_to(output_root)
    config_name = re.sub(r"[^A-Za-z0-9._-]+", "-", "-".join(relative.parts))
    config_name = config_name.strip("-") or output_slug(hostname)
    archive_path = output_dir.with_name(f"{output_dir.name}.zip")
    return UrlBuildPaths(
        output_dir=output_dir,
        config_path=config_dir / f"{config_name}.yaml",
        archive_path=archive_path,
    )


def display_path(path: str | Path, cwd: str | Path | None = None) -> str:
    """Show a path relative to the working directory when possible."""
    cwd_path = Path(cwd or Path.cwd()).resolve()
    resolved = Path(path).resolve()
    try:
        return resolved.relative_to(cwd_path).as_posix()
    except ValueError:
        return str(path)


def build_config_data(
    options: UrlBuildOptions,
    output_dir: str | Path,
    cwd: str | Path | None = None,
) -> dict:
    """Construct the YAML data for a valid URL-derived configuration."""
    crawl_defaults = CrawlConfig()
    index_defaults = IndexConfig()
    return {
        "client_name": options.hostname,
        "sources": {
            "urls": [options.url],
            "allowed_domains": [options.hostname],
        },
        "crawl": {
            "max_depth": options.max_depth,
            "max_pages": options.max_pages,
            "delay_seconds": crawl_defaults.delay_seconds,
            "timeout_seconds": crawl_defaults.timeout_seconds,
            "retries": crawl_defaults.retries,
            "user_agent": crawl_defaults.user_agent,
            "include_subdomains": options.include_subdomains,
        },
        "chunking": {
            "strategy": options.chunking_strategy,
            "size": options.chunk_size,
            "overlap": options.chunk_overlap,
        },
        "index": {
            "bm25": index_defaults.bm25,
            "dense": index_defaults.dense,
            "embedding_model": index_defaults.embedding_model,
            "ranking_modes": list(options.ranking_modes),
        },
        "output_dir": display_path(output_dir, cwd),
    }


def _is_generated_config(path: Path) -> bool:
    try:
        head = path.read_text(encoding="utf-8")[: len(GENERATED_CONFIG_MARKER) + 2]
    except (OSError, UnicodeDecodeError):
        return False
    return head.startswith(GENERATED_CONFIG_MARKER)


def check_destination_collisions(paths: UrlBuildPaths, *, overwrite: bool) -> None:
    if paths.output_dir.exists() and not paths.output_dir.is_dir():
        raise UrlBuildError(
            f"output path exists and is not a directory: {paths.output_dir}"
        )
    if paths.output_dir.exists() and not overwrite:
        raise UrlBuildError(
            f"output directory already exists: {paths.output_dir}; "
            "use --overwrite to rebuild it"
        )
    if paths.archive_path.exists() and not paths.archive_path.is_file():
        raise UrlBuildError(
            f"ZIP path exists and is not a file: {paths.archive_path}"
        )
    if paths.archive_path.exists() and not overwrite:
        raise UrlBuildError(
            f"ZIP archive already exists: {paths.archive_path}; "
            "use --overwrite to replace it"
        )
    if paths.config_path.exists():
        if not overwrite:
            raise UrlBuildError(
                f"generated configuration already exists: {paths.config_path}; "
                "use --overwrite to replace it"
            )
        if not _is_generated_config(paths.config_path):
            raise UrlBuildError(
                "refusing to overwrite a configuration not created by this "
                f"workflow: {paths.config_path}"
            )


def write_generated_config(
    paths: UrlBuildPaths,
    data: dict,
    *,
    overwrite: bool,
) -> Path:
    """Atomically write a generated YAML configuration after collision checks."""
    check_destination_collisions(paths, overwrite=overwrite)
    paths.config_path.parent.mkdir(parents=True, exist_ok=True)
    content = (
        GENERATED_CONFIG_MARKER
        + "\n"
        + yaml.safe_dump(data, sort_keys=False, allow_unicode=True)
    )
    tmp_path = paths.config_path.with_name(f".{paths.config_path.name}.tmp")
    tmp_path.write_text(content, encoding="utf-8")
    os.replace(tmp_path, paths.config_path)
    return paths.config_path


def prepare_output_directories(paths: UrlBuildPaths) -> None:
    """Remove prior outputs after an explicit overwrite was accepted."""
    if paths.output_dir.exists():
        shutil.rmtree(paths.output_dir)
    try:
        paths.archive_path.unlink()
    except FileNotFoundError:
        pass


def _reader(input_fn):
    return input_fn or input


def _ask(prompt: str, *, input_fn=None) -> str:
    try:
        return _reader(input_fn)(prompt)
    except EOFError as exc:
        raise UrlBuildError("input ended before configuration was complete") from exc


def _prompt_int(
    prompt: str,
    default: int,
    *,
    minimum: int,
    input_fn=None,
    print_fn=print,
) -> int:
    while True:
        raw = _ask(f"{prompt} [{default}]: ", input_fn=input_fn).strip()
        if not raw:
            return default
        try:
            value = int(raw)
        except ValueError:
            print_fn("Please enter a whole number.")
            continue
        if value < minimum:
            print_fn(f"Please enter a number greater than or equal to {minimum}.")
            continue
        return value


def _prompt_bool(
    prompt: str,
    default: bool,
    *,
    input_fn=None,
    print_fn=print,
) -> bool:
    suffix = "[Y/n]" if default else "[y/N]"
    while True:
        raw = _ask(f"{prompt} {suffix}: ", input_fn=input_fn).strip().lower()
        if not raw:
            return default
        if raw in ("y", "yes"):
            return True
        if raw in ("n", "no"):
            return False
        print_fn("Please answer yes or no.")


def _normalize_strategy(value: str) -> str:
    lowered = value.strip().lower()
    aliases = {
        "1": "fixed",
        "2": "sentence",
        "3": "paragraph",
        "fixed-size": "fixed",
        "sentence-based": "sentence",
        "paragraph-based": "paragraph",
    }
    strategy = aliases.get(lowered, lowered)
    if strategy not in VALID_CHUNKING_STRATEGIES:
        raise UrlBuildError(
            f"invalid chunking strategy {value!r}; "
            f"choose from {', '.join(VALID_CHUNKING_STRATEGIES)}"
        )
    return strategy


def _prompt_strategy(default: str, *, input_fn=None, print_fn=print) -> str:
    print_fn("Chunking strategy:")
    for index, (strategy, label) in enumerate(STRATEGY_MENU, start=1):
        default_mark = " (default)" if strategy == default else ""
        print_fn(f"  {index}. {label}{default_mark}")
    default_number = next(
        str(index)
        for index, (strategy, _) in enumerate(STRATEGY_MENU, start=1)
        if strategy == default
    )
    while True:
        raw = _ask(
            f"Choose strategy [{default_number}]: ",
            input_fn=input_fn,
        ).strip()
        if not raw:
            return default
        try:
            return _normalize_strategy(raw)
        except UrlBuildError as exc:
            print_fn(str(exc))


def parse_ranking_modes(value: str) -> tuple[str, ...]:
    if not isinstance(value, str):
        raise UrlBuildError("ranking modes must be a comma-separated string")
    modes: list[str] = []
    for item in value.split(","):
        mode = item.strip().lower()
        if not mode:
            continue
        if mode not in VALID_RANKING_MODES:
            raise UrlBuildError(
                f"unsupported ranking mode {mode!r}; "
                f"choose from {', '.join(VALID_RANKING_MODES)}"
            )
        if mode not in modes:
            modes.append(mode)
    if not modes:
        raise UrlBuildError("at least one ranking mode is required")
    return tuple(modes)


def _prompt_ranking(default: str, *, input_fn=None, print_fn=print) -> tuple[str, ...]:
    while True:
        raw = _ask(f"Ranking modes [{default}]: ", input_fn=input_fn).strip()
        try:
            return parse_ranking_modes(raw or default)
        except UrlBuildError as exc:
            print_fn(str(exc))


def _validated_supplied_int(
    value: int | None,
    name: str,
    *,
    minimum: int,
    interactive: bool,
    print_fn=print,
) -> int | None:
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, int) or value < minimum:
        message = f"{name} must be an integer greater than or equal to {minimum}"
        if not interactive:
            raise UrlBuildError(message)
        print_fn(message + ".")
        return None
    return value


def collect_url_build_options(
    *,
    url: str | None,
    max_pages: int | None,
    max_depth: int | None,
    include_subdomains: bool | None,
    chunking_strategy: str | None,
    chunk_size: int | None,
    chunk_overlap: int | None,
    ranking_modes: str | None,
    output: str | None,
    yes: bool,
    input_fn=None,
    print_fn=print,
    cwd: str | Path | None = None,
) -> tuple[UrlBuildOptions, UrlBuildPaths] | None:
    """Collect URL workflow options, prompting only when appropriate.

    Returns ``None`` when the user cancels at the confirmation prompt.
    """
    interactive = not yes
    if interactive:
        print_fn("KBForge - Website Knowledge Base Builder")
        print_fn("")

    if url is not None:
        normalized_url, hostname = validate_website_url(url)
    elif not interactive:
        raise UrlBuildError("--url is required in non-interactive mode (with --yes)")
    else:
        while True:
            raw = _ask("Enter website URL: ", input_fn=input_fn)
            try:
                normalized_url, hostname = validate_website_url(raw)
                break
            except UrlBuildError as exc:
                print_fn(str(exc))

    crawl_defaults = CrawlConfig()
    chunk_defaults = ChunkingConfig()

    max_pages_value = _validated_supplied_int(
        max_pages,
        "maximum pages",
        minimum=1,
        interactive=interactive,
        print_fn=print_fn,
    )
    if max_pages_value is None:
        max_pages_value = (
            _prompt_int(
                "Maximum pages to crawl",
                crawl_defaults.max_pages,
                minimum=1,
                input_fn=input_fn,
                print_fn=print_fn,
            )
            if interactive
            else crawl_defaults.max_pages
        )

    max_depth_value = _validated_supplied_int(
        max_depth,
        "maximum crawl depth",
        minimum=0,
        interactive=interactive,
        print_fn=print_fn,
    )
    if max_depth_value is None:
        max_depth_value = (
            _prompt_int(
                "Maximum crawl depth",
                crawl_defaults.max_depth,
                minimum=0,
                input_fn=input_fn,
                print_fn=print_fn,
            )
            if interactive
            else crawl_defaults.max_depth
        )

    if include_subdomains is None:
        include_subdomains_value = (
            _prompt_bool(
                "Include subdomains?",
                False,
                input_fn=input_fn,
                print_fn=print_fn,
            )
            if interactive
            else False
        )
    else:
        include_subdomains_value = include_subdomains

    if chunking_strategy is None:
        strategy = (
            _prompt_strategy(
                chunk_defaults.strategy,
                input_fn=input_fn,
                print_fn=print_fn,
            )
            if interactive
            else chunk_defaults.strategy
        )
    else:
        try:
            strategy = _normalize_strategy(chunking_strategy)
        except UrlBuildError as exc:
            if not interactive:
                raise
            print_fn(str(exc))
            strategy = _prompt_strategy(
                chunk_defaults.strategy,
                input_fn=input_fn,
                print_fn=print_fn,
            )

    chunk_size_value = _validated_supplied_int(
        chunk_size,
        "maximum words per chunk",
        minimum=1,
        interactive=interactive,
        print_fn=print_fn,
    )
    if chunk_size_value is None:
        chunk_size_value = (
            _prompt_int(
                "Maximum words per chunk",
                chunk_defaults.size,
                minimum=1,
                input_fn=input_fn,
                print_fn=print_fn,
            )
            if interactive
            else chunk_defaults.size
        )

    if chunk_overlap is None:
        overlap = (
            min(chunk_defaults.overlap, chunk_size_value - 1)
            if strategy == "fixed"
            else 0
        )
    else:
        if (
            isinstance(chunk_overlap, bool)
            or not isinstance(chunk_overlap, int)
            or chunk_overlap < 0
        ):
            raise UrlBuildError("chunk overlap must be an integer >= 0")
        if chunk_overlap >= chunk_size_value:
            raise UrlBuildError("chunk overlap must be smaller than chunk size")
        overlap = chunk_overlap

    if ranking_modes is None:
        ranking_modes_value = (
            _prompt_ranking(
                ",".join(VALID_RANKING_MODES),
                input_fn=input_fn,
                print_fn=print_fn,
            )
            if interactive
            else tuple(VALID_RANKING_MODES)
        )
    else:
        try:
            ranking_modes_value = parse_ranking_modes(ranking_modes)
        except UrlBuildError as exc:
            if not interactive:
                raise
            print_fn(str(exc))
            ranking_modes_value = _prompt_ranking(
                ",".join(VALID_RANKING_MODES),
                input_fn=input_fn,
                print_fn=print_fn,
            )

    default_display = display_path(
        default_output_path(hostname, cwd),
        cwd,
    )
    if output is None:
        if interactive:
            output_value = (
                _ask(
                    f"Output directory [{default_display}]: ",
                    input_fn=input_fn,
                ).strip()
                or None
            )
        else:
            output_value = None
    else:
        output_value = output

    while True:
        try:
            paths = resolve_build_paths(output_value, hostname, cwd)
            break
        except UrlBuildError as exc:
            if not interactive:
                raise
            print_fn(str(exc))
            output_value = (
                _ask(
                    f"Output directory [{default_display}]: ",
                    input_fn=input_fn,
                ).strip()
                or None
            )

    options = UrlBuildOptions(
        url=normalized_url,
        hostname=hostname,
        max_pages=max_pages_value,
        max_depth=max_depth_value,
        include_subdomains=include_subdomains_value,
        chunking_strategy=strategy,
        chunk_size=chunk_size_value,
        chunk_overlap=overlap,
        ranking_modes=ranking_modes_value,
        output=output_value,
    )

    if interactive:
        print_fn("")
        print_fn("Review configuration:")
        print_fn(f"  Website: {options.url}")
        print_fn(f"  Maximum pages: {options.max_pages}")
        print_fn(f"  Maximum depth: {options.max_depth}")
        print_fn(
            "  Include subdomains: "
            + ("yes" if options.include_subdomains else "no")
        )
        print_fn(
            f"  Chunking strategy: {STRATEGY_LABELS[options.chunking_strategy]}"
        )
        print_fn(f"  Maximum words per chunk: {options.chunk_size}")
        print_fn(f"  Ranking modes: {', '.join(options.ranking_modes)}")
        print_fn(f"  Output directory: {display_path(paths.output_dir, cwd)}")
        print_fn("")
        if not _prompt_bool(
            "Start build?",
            True,
            input_fn=input_fn,
            print_fn=print_fn,
        ):
            print_fn("Build cancelled.")
            return None

    return options, paths


def prepare_url_build(
    options: UrlBuildOptions,
    paths: UrlBuildPaths,
    *,
    overwrite: bool,
    cwd: str | Path | None = None,
) -> dict:
    """Check collisions, write the generated YAML and clear old outputs."""
    check_destination_collisions(paths, overwrite=overwrite)
    data = build_config_data(options, paths.output_dir, cwd)
    write_generated_config(paths, data, overwrite=overwrite)
    prepare_output_directories(paths)
    return data
